-- composition of rule kernels OmitOrderBy x OrderBySubq (sqlite), template union
CREATE VIEW n1 AS SELECT 7 AS c0 UNION SELECT 1 AS c0;
SELECT count(*) FROM (SELECT 1 AS k FROM (WITH cte1 AS MATERIALIZED (SELECT MIN (CAST('abc' AS TEXT), CAST('ß' AS TEXT)) AS c0 FROM (SELECT FORMAT ('%s|%s', '{"k": 1, "a": [1, 2]}', '{}') AS c0, '2000-01-01 00:00:00' AS c1 FROM n1 AS a1 GROUP BY a1.c0) AS a2 WHERE TRUE GROUP BY a2.c1) SELECT 7 AS c0, (-42) AS c1, CAST(100 AS INTEGER) AS c2 FROM cte1 AS a3 WHERE FALSE) AS ka UNION ALL SELECT 2 AS k FROM (SELECT FALSE AS c0, '{}' AS c1 FROM (SELECT '2024-12-31' AS c0, CAST('ß' AS TEXT) AS c1, 100 AS c2 FROM t2 AS a1 ORDER BY 2) AS a2 ORDER BY 2) AS kb) AS u;
-- pgfuzz:check kernel:union SELECT (SELECT count(*) FROM (WITH cte1 AS MATERIALIZED (SELECT MIN (CAST('abc' AS TEXT), CAST('ß' AS TEXT)) AS c0 FROM (SELECT FORMAT ('%s|%s', '{"k": 1, "a": [1, 2]}', '{}') AS c0, '2000-01-01 00:00:00' AS c1 FROM n1 AS a1 GROUP BY a1.c0) AS a2 WHERE TRUE GROUP BY a2.c1) SELECT 7 AS c0, (-42) AS c1, CAST(100 AS INTEGER) AS c2 FROM cte1 AS a3 WHERE FALSE) AS ka) + (SELECT count(*) FROM (SELECT FALSE AS c0, '{}' AS c1 FROM (SELECT '2024-12-31' AS c0, CAST('ß' AS TEXT) AS c1, 100 AS c2 FROM t2 AS a1 ORDER BY 2) AS a2 ORDER BY 2) AS kb)
